39	function collectCheckpointSections(
40	  content: string,
41	  path: string,
42	): { sections: Partial<Record<CheckpointSectionName, string>>; diagnostics: Diagnostic[] } {
43	  const lines = content.replace(/\r\n?/g, "\n").split("\n");
44	  const positions = new Map<CheckpointSectionName, number[]>();
45	  for (const name of CHECKPOINT_SECTION_NAMES) positions.set(name, []);
46	
47	  let fence: { marker: "`" | "~"; length: number } | undefined;
48	  let htmlBlockEnd: RegExp | "blank" | undefined;
49	  let managedSnapshot = false;
50	  const orderedMatches: Array<{ name: CheckpointSectionName; index: number }> = [];
51	  const h2Positions: number[] = [];
52	  for (const [index, line] of lines.entries()) {
53	    if (managedSnapshot) {
54	      if (line === HANDOFF_SNAPSHOT_END) managedSnapshot = false;
55	      continue;
56	    }
57	
58	    if (fence !== undefined) {
59	      const closingFence = /^(?: {0,3})(`{3,}|~{3,})[ \t]*$/.exec(line)?.[1];
60	      if (
61	        closingFence !== undefined &&
62	        closingFence[0] === fence.marker &&
63	        closingFence.length >= fence.length
64	      ) {
65	        fence = undefined;
66	      }
67	      continue;
68	    }
69	
70	    if (htmlBlockEnd !== undefined) {
71	      const closes = htmlBlockEnd === "blank" ? line.trim() === "" : htmlBlockEnd.test(line);
72	      if (closes) htmlBlockEnd = undefined;
73	      continue;
74	    }
75	
76	    if (/^ {0,3}>/.test(line) || /^(?: {4}|\t)/.test(line)) continue;
77	    const openingMatch = /^(?: {0,3})(`{3,}|~{3,})(.*)$/.exec(line);
78	    const openingFence = openingMatch?.[1];
79	    const infoString = openingMatch?.[2];
80	    if (
81	      openingFence !== undefined &&
82	      infoString !== undefined &&
83	      !(openingFence[0] === "`" && infoString.includes("`"))
84	    ) {
85	      fence = {
86	        marker: openingFence[0] as "`" | "~",
87	        length: openingFence.length,
88	      };
89	      continue;
90	    }
91	    if (line === HANDOFF_SNAPSHOT_START) {
92	      managedSnapshot = true;
93	      continue;
94	    }
95	    const htmlOpening = htmlBlockOpening(line);
96	    if (htmlOpening !== undefined) {
97	      if (
98	        htmlOpening.end === "blank" ||
99	        !htmlOpening.end.test(line.slice(htmlOpening.openingLength))
100	      ) {
101	        htmlBlockEnd = htmlOpening.end;
102	      }
103	      continue;
104	    }
105	    if (line.startsWith("## ")) h2Positions.push(index);
106	    for (const name of CHECKPOINT_SECTION_NAMES) {
107	      if (line === `## ${name}`) {
108	        const matches = positions.get(name);
109	        if (matches === undefined) throw new Error(`Missing checkpoint parser slot: ${name}`);
110	        matches.push(index);
111	        orderedMatches.push({ name, index });
112	      }
113	    }
114	  }
115	
116	  const diagnostics: Diagnostic[] = [];
117	  const sections: Partial<Record<CheckpointSectionName, string>> = {};
118	  for (const index of h2Positions) {
119	    const line = lines[index];
120	    if (line === undefined) continue;
121	    const heading = line.slice(3);
122	    if (!CHECKPOINT_SECTION_NAMES.includes(heading as CheckpointSectionName)) {
123	      diagnostics.push({
124	        level: "error",
125	        code: "E_CHECKPOINT_SECTION_UNKNOWN",
126	        message: `Checkpoint contains unsupported H2 section: ${heading}.`,
127	        path,
128	      });
129	    }
130	  }
131	  for (const name of CHECKPOINT_SECTION_NAMES) {
132	    const matches = positions.get(name) ?? [];
133	    if (matches.length !== 1) {
134	      diagnostics.push({
135	        level: "error",
136	        code:
137	          matches.length === 0 ? "E_CHECKPOINT_SECTION_MISSING" : "E_CHECKPOINT_SECTION_DUPLICATE",
138	        message:
139	          matches.length === 0
140	            ? `Checkpoint is missing required section: ${name}.`
141	            : `Checkpoint contains more than one '${name}' section.`,
142	        path,
143	      });
144	      continue;
145	    }
146	    const match = matches[0];
147	    if (match === undefined) continue;
148	    const start = match + 1;
149	    let end = lines.length;
150	    end = h2Positions.find((index) => index >= start) ?? lines.length;
151	    const body = lines.slice(start, end).join("\n").trim();
152	    if (body.length === 0) {
153	      diagnostics.push({
154	        level: "error",
155	        code: "E_CHECKPOINT_SECTION_EMPTY",
156	        message: `Checkpoint section must not be empty: ${name}.`,
157	        path,
158	      });
159	    } else {
160	      sections[name] = body;
161	    }
162	  }
163	  if (
164	    orderedMatches.length === CHECKPOINT_SECTION_NAMES.length &&
165	    orderedMatches.some((match, index) => match.name !== CHECKPOINT_SECTION_NAMES[index])
166	  ) {
167	    diagnostics.push({
168	      level: "error",
169	      code: "E_CHECKPOINT_SECTION_ORDER",
170	      message: `Checkpoint sections must appear in this order: ${CHECKPOINT_SECTION_NAMES.join(", ")}.`,
171	      path,
172	    });
173	  }
174	  return { sections, diagnostics };
175	}
