177	const COMMONMARK_BLOCK_TAG =
178	  /^(?: {0,3})<\/?(?:address|article|aside|base|basefont|blockquote|body|caption|center|col|colgroup|dd|details|dialog|dir|div|dl|dt|fieldset|figcaption|figure|footer|form|frame|frameset|h[1-6]|head|header|hr|html|iframe|legend|li|link|main|menu|menuitem|nav|noframes|ol|optgroup|option|p|param|search|section|summary|table|tbody|td|tfoot|th|thead|title|tr|track|ul)(?:[ \t\n/>]|$)/i;
179	const COMPLETE_HTML_TAG =
180	  /^(?: {0,3})<\/?[A-Za-z][A-Za-z0-9-]*(?:[ \t]+[A-Za-z_:][A-Za-z0-9_.:-]*(?:[ \t]*=[ \t]*(?:[^ "'=<>`]+|'[^']*'|"[^"]*"))?)*[ \t]*\/?>[ \t]*$/;
181	
182	function htmlBlockOpening(
183	  line: string,
184	): { end: RegExp | "blank"; openingLength: number } | undefined {
185	  const prefix = /^(?: {0,3})/.exec(line)?.[0] ?? "";
186	  const candidate = line.slice(prefix.length);
187	  const rawTag = /^<(script|pre|style|textarea)(?:[ \t>]|$)/i.exec(candidate)?.[1];
188	  if (rawTag !== undefined) {
189	    return { end: new RegExp(`</${rawTag}[ \\t]*>`, "i"), openingLength: prefix.length };
190	  }
191	  if (candidate.startsWith("<!--")) return { end: /-->/, openingLength: prefix.length + 4 };
192	  if (candidate.startsWith("<?")) return { end: /\?>/, openingLength: prefix.length + 2 };
193	  if (/^<![A-Z]/.test(candidate)) return { end: />/, openingLength: prefix.length + 2 };
194	  if (candidate.startsWith("<![CDATA[")) {
195	    return { end: /\]\]>/, openingLength: prefix.length + 9 };
196	  }
197	  if (COMMONMARK_BLOCK_TAG.test(line) || COMPLETE_HTML_TAG.test(line)) {
198	    return { end: "blank", openingLength: line.length };
199	  }
200	  return undefined;
201	}
