252	    left.metadata.inode === right.metadata.inode &&
253	    left.metadata.size === right.metadata.size &&
254	    left.metadata.mtimeNs === right.metadata.mtimeNs &&
255	    left.metadata.ctimeNs === right.metadata.ctimeNs &&
256	    left.metadata.linkCount === right.metadata.linkCount
